// Generated by Doc Writer: the theme toggle, and the page list
// folded on a phone.
(function () {
  'use strict';
  var root = document.documentElement;
  var KEY = 'team-docs-theme';
  function read() {
    try {
      return window.localStorage.getItem(KEY);
    } catch (e) {
      return null;
    }
  }
  var chosen = read();
  if (chosen === 'light' || chosen === 'dark') {
    root.setAttribute('data-theme', chosen);
  }
  function current() {
    var theme = root.getAttribute('data-theme');
    if (theme === 'light' || theme === 'dark') {
      return theme;
    }
    return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches
      ? 'dark'
      : 'light';
  }
  document.addEventListener('DOMContentLoaded', function () {
    var button = document.querySelector('.theme-toggle');
    if (button) {
      var sync = function () {
        button.setAttribute('aria-pressed', current() === 'dark' ? 'true' : 'false');
      };
      button.hidden = false;
      sync();
      button.addEventListener('click', function () {
        var next = current() === 'dark' ? 'light' : 'dark';
        root.setAttribute('data-theme', next);
        try {
          window.localStorage.setItem(KEY, next);
        } catch (e) {
          // a private window or a local file: the choice lasts for this page only
        }
        sync();
      });
    }
    var menu = document.querySelector('.nav-menu');
    if (menu && window.matchMedia && window.matchMedia('(max-width: 900px)').matches) {
      menu.open = false;
    }
  });
})();
